-- WRONG: email as primary key (users change their email)
CREATE TABLE users (
  email VARCHAR(255) PRIMARY KEY,
  name  VARCHAR(100)
);

-- RIGHT: generated id + unique constraint
CREATE TABLE users (
  id    BIGSERIAL PRIMARY KEY,
  email VARCHAR(255) NOT NULL UNIQUE,
  name  VARCHAR(100) NOT NULL
);

-- Before: users(id, name, phones, zip, city)
--   phones = "555-1111, 555-2222"  -> breaks 1NF
--   city depends on zip, not on id  -> breaks 3NF

CREATE TABLE zip_codes (
  zip  CHAR(8) PRIMARY KEY,
  city VARCHAR(100) NOT NULL
);

CREATE TABLE users (
  id   SERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  zip  CHAR(8) REFERENCES zip_codes(zip)
);

CREATE TABLE phones (
  user_id INT NOT NULL REFERENCES users(id),
  number  VARCHAR(20) NOT NULL
);

-- WRONG: if any order has customer_id NULL, this returns zero rows
SELECT name FROM customers
WHERE id NOT IN (SELECT customer_id FROM orders);

-- RIGHT: NOT EXISTS is not affected by NULL
SELECT c.name FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id
);

CREATE INDEX idx_users_email ON users (email);

EXPLAIN SELECT * FROM users WHERE email = 'ana@example.com';
-- Before the index: Seq Scan on users
-- After:            Index Scan using idx_users_email on users

-- WRONG: lower(email) does not use idx_users_email
SELECT * FROM users WHERE lower(email) = 'ana@example.com';

-- RIGHT: index the same expression the filter uses
CREATE INDEX idx_users_email_lower ON users (lower(email));

