BEGIN;
UPDATE accounts SET balance = balance - 50 WHERE id = 1;  -- debit
UPDATE accounts SET balance = balance + 50 WHERE id = 2;  -- credit
COMMIT;   -- both changes take effect together

BEGIN;
UPDATE accounts SET balance = balance - 50 WHERE id = 1;
-- an error happens here
ROLLBACK; -- the debit is undone

// WRONG: without @Transactional, each save() is its own transaction
public void transfer(Long from, Long to, BigDecimal amount) {
    accounts.save(debit(from, amount));   // already saved
    accounts.save(credit(to, amount));    // if this fails, the debit stays
}

// RIGHT: both operations in one transaction
@Transactional
public void transfer(Long from, Long to, BigDecimal amount) {
    accounts.save(debit(from, amount));
    accounts.save(credit(to, amount));    // fails: both are rolled back
}

